import json,subprocess
for p in (54,55):
    old=json.loads(subprocess.run(['git','show',f'HEAD:data/verification/page-{p}.json'],capture_output=True,text=True).stdout)
    new=json.load(open(f'data/verification/page-{p}.json'))
    def strip(d):
        d=json.loads(json.dumps(d))
        for e in d['entries']:
            e.pop('note_fa',None)
            for n in e['nodes']: n.pop('derivation_fa',None)
        return d
    print(p,'content identical after stripping fa fields:', strip(new)==old)
